PRAGMA foreign_keys=ON;
CREATE TABLE teachers(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at INTEGER NOT NULL);
CREATE TABLE teacher_sessions(token_hash TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES teachers(id),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX teacher_sessions_owner ON teacher_sessions(teacher_id,expires_at);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE quizzes(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES teachers(id),title TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX quizzes_owner ON quizzes(teacher_id,archived,updated_at);
CREATE TABLE questions(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES teachers(id),type TEXT NOT NULL CHECK(type IN('mc','tf','short')),prompt TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',topic TEXT NOT NULL DEFAULT '',difficulty TEXT NOT NULL DEFAULT 'media',image TEXT,explanation TEXT NOT NULL DEFAULT '',answer_json TEXT NOT NULL,points REAL NOT NULL CHECK(points>0 AND points<=100),revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE INDEX questions_owner ON questions(teacher_id,subject,topic);
CREATE TABLE choices(id TEXT PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,position INTEGER NOT NULL,text TEXT NOT NULL,UNIQUE(question_id,position));
CREATE TABLE quiz_questions(quiz_id TEXT NOT NULL REFERENCES quizzes(id),question_id TEXT NOT NULL REFERENCES questions(id),position INTEGER NOT NULL,PRIMARY KEY(quiz_id,question_id),UNIQUE(quiz_id,position));
CREATE TABLE rooms(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES teachers(id),code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,open INTEGER NOT NULL DEFAULT 1 CHECK(open IN(0,1)),created_at INTEGER NOT NULL);
CREATE INDEX rooms_owner ON rooms(teacher_id,created_at);
CREATE TABLE assessment_sessions(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id),teacher_id TEXT NOT NULL REFERENCES teachers(id),quiz_id TEXT NOT NULL REFERENCES quizzes(id),title TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('self','teacher','teams','exit')),state TEXT NOT NULL CHECK(state IN('waiting','running','paused','ended')),questions_json TEXT NOT NULL,active_question INTEGER NOT NULL DEFAULT 0,team_count INTEGER NOT NULL DEFAULT 2 CHECK(team_count BETWEEN 2 AND 8),release_results INTEGER NOT NULL DEFAULT 0 CHECK(release_results IN(0,1)),created_at INTEGER NOT NULL,started_at INTEGER,ended_at INTEGER);
CREATE UNIQUE INDEX one_active_per_room ON assessment_sessions(room_id) WHERE state<>'ended';
CREATE INDEX sessions_owner ON assessment_sessions(teacher_id,created_at);
CREATE TABLE participants(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES assessment_sessions(id),name TEXT NOT NULL,normalized_name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,team INTEGER NOT NULL DEFAULT 0,joined_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,completed_at INTEGER,UNIQUE(session_id,normalized_name));
CREATE INDEX participants_session ON participants(session_id,last_seen);
CREATE TABLE answers(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES participants(id),session_id TEXT NOT NULL REFERENCES assessment_sessions(id),question_id TEXT NOT NULL,answer_json TEXT NOT NULL,correct INTEGER NOT NULL CHECK(correct IN(0,1)),score REAL NOT NULL,submitted_at INTEGER NOT NULL,UNIQUE(participant_id,question_id));
CREATE INDEX answers_session ON answers(session_id,participant_id);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,teacher_id TEXT REFERENCES teachers(id),action TEXT NOT NULL,entity_id TEXT,created_at INTEGER NOT NULL);
CREATE INDEX audit_owner ON audit_events(teacher_id,created_at);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
